import React from 'react';
import { useForm } from 'react-hook-form';
import { leadsAPI } from '../services/api';

const LandingForm = () => {
  const { register, handleSubmit, formState: { errors }, reset } = useForm();

  const onSubmit = async (data) => {
    try {
      await leadsAPI.createLead(data);
      alert('Cảm ơn! Lead của bạn đã được gửi.');
      reset();
    } catch (error) {
      alert('Lỗi: ' + error.response.data.error);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="lead-form">
      <input
        {...register('name', { required: 'Tên là bắt buộc' })}
        placeholder="Tên của bạn"
      />
      {errors.name && <p>{errors.name.message}</p>}

      <input
        {...register('email', { required: 'Email là bắt buộc', pattern: { value: /^\S+@\S+$/i, message: 'Email không hợp lệ' } })}
        placeholder="Email"
        type="email"
      />
      {errors.email && <p>{errors.email.message}</p>}

      <input
        {...register('phone', { required: 'Số điện thoại là bắt buộc' })}
        placeholder="Số điện thoại"
        type="tel"
      />
      {errors.phone && <p>{errors.phone.message}</p>}

      <input {...register('company')} placeholder="Công ty" />
      <input {...register('position')} placeholder="Vị trí công việc" />

      <button type="submit">Gửi Leads</button>
    </form>
  );
};

export default LandingForm;
